import{_ as t,a as n}from"./chunks/built-with-blockly-badge-black.BLndjqRJ.js";import{_ as r,o as i,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const o="/assets/blocks-for-ha/ui/de.png",k=JSON.parse('{"title":"Blocks for HA","description":"Native Home-Assistant-Automationen mit visuellen Blocks erstellen.","frontmatter":{"title":"Blocks for HA","description":"Native Home-Assistant-Automationen mit visuellen Blocks erstellen."},"headers":[],"relativePath":"projects/blocks-for-ha/index.md","filePath":"projects/blocks-for-ha/index.md","lastUpdated":1793123188000}'),d={name:"projects/blocks-for-ha/index.md"};function l(u,e,g,h,c,b){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="blocks-for-ha" tabindex="-1">Blocks for HA <a class="header-anchor" href="#blocks-for-ha" aria-label="Permalink to &quot;Blocks for HA&quot;">​</a></h1><p>Neu in <strong>0.1.66</strong>: Unnötige Beispieltexte in allen Kategorien entfernt, auch MQTT, Objekte, Listen, Umwandlungen und Ersatzwerte. Assist-Antwort und Jinja-Text starten leer und einzeilig. Trennzeichen, gültige JSON-Grundstrukturen und technische Einstellungen bleiben erhalten; ebenso vorhandene Projektwerte.</p><p>Neu in <strong>0.1.65</strong>: Einzeiliger Textblock ohne Zusatzzeile, neue Textfelder leer und keine vorbelegte „Hallo“-Verbindung bei „Erstelle Text aus“. Bestehende Texte bleiben erhalten.</p><p>Neu in <strong>0.1.64</strong>: Zweckbezogene Templates für Text, Uhrzeitbereich, Wertänderung und typisierte falls/sonst-Werte. Freier Jinja-Code steht einmal unter Templates. App-/Automationssteuerung zweizeilig wie bei ioBroker. Vollständig DE/EN/FR. <a href="./system-template">Anleitung und Bilder</a>.</p><p>Neu in <strong>0.1.63</strong>: Template mit direkten Werte-Andockpunkten wie „Datei schreiben“ bei ioBroker, automatischem zusätzlichem Eingang und passenden Typen. Keine Zahnräder an Template-Bausteinen. Alte Ketten werden beim Laden umgewandelt. <a href="./system-template">Anleitung</a>.</p><p>Neu in <strong>0.1.62</strong>: Entitäts-ID und gemeinsame Entitätswerte unter System, einmalige Momentaufnahme, App- und Automationssteuerung sowie ein visueller Template-Baukasten. Text, Mathematik, Variablen und Systemwerte zusammenstecken; Zahlenformat, Ersatzwert, Zeilenumbruch und bedingte Ausgabe ergänzen. Jinja und HA-Vorschau per Rechtsklick. DE/EN/FR. <a href="./system-template">Anleitung</a>.</p><p>Neu in <strong>0.1.61</strong>: <strong>und / oder / nicht</strong> als getrennte Blöcke. Optionale HA-Felder einzeln über das Zahnrad ergänzen, entfernen und anordnen. Pflichtfelder und importierte Werte bleiben erhalten. DE/EN/FR. <a href="./advanced">Geprüfte Blöcke und Bedienung</a>.</p><p>Neu in <strong>0.1.60</strong>: <strong>Zeitplan</strong> mit Wizard/Einfach/CRON-Popup, Feldreitern und optionalen Sekunden, Wochentage, Auslöserdaten und Sonnenversatz. Erweiterte native HA-Auslöser direkt unter <strong>Auslöser</strong>. DE/EN/FR. <a href="./time">ioBroker-Vergleich und Grenzen</a>.</p><p>Neu in <strong>0.1.59</strong>: ioBroker-nahe Beschriftungen und Zahnrad-Popups, <strong>Kommentar</strong> unter System mit YAML-Kommentaren und <strong>MQTT-Nachricht</strong> unter Nachrichten ohne Instanzauswahl. Alle Texte und Blockbilder in DE/EN/FR. <a href="./blocks">Details und Bilder</a>.</p><h2 id="leerer-start-seit-0-1-52" tabindex="-1">Leerer Start seit 0.1.52 <a class="header-anchor" href="#leerer-start-seit-0-1-52" aria-label="Permalink to &quot;Leerer Start seit 0.1.52&quot;">​</a></h2><p>Seit <strong>0.1.54</strong> bietet <strong>Neue Automation</strong> drei Optionen: <strong>Sichern und neu beginnen</strong>, <strong>Ohne Sicherung neu beginnen</strong> oder <strong>Abbrechen</strong>. Die Sicherung wird vor dem Leeren als <code>.blocks.json</code> heruntergeladen und enthält Blocks, Automationsdaten und eingefügten YAML-Code. Über <strong>Projekt öffnen</strong> lässt sie sich wiederherstellen. Abbrechen oder Escape erhält den aktuellen Stand. Beim Neubeginn werden Blocks, Rückgängig-Verlauf, Name, Beschreibung und Eingaben zurückgesetzt. Sprache, Darstellung, HA-Verbindung und installierte Blockpakete bleiben erhalten.</p><p>Ohne gespeichertes Projekt startet der Editor vollständig leer. Ziehe <strong>Automation</strong> aus der Kategorie <strong>System</strong> auf die Arbeitsfläche oder importiere YAML. Beim Import in einen leeren Editor ist „Aktuelle Automation vollständig ersetzen“ nicht erforderlich. Beispiele werden ausschließlich über <strong>Beispiel laden</strong> geöffnet.</p><p>Gespeicherte Projekte werden beim nächsten Start wiederhergestellt. Auch ein leeres Projekt bleibt beim Neuladen und Sprachwechsel leer. Kann der Browserstand nicht geladen werden, öffnet sich ein leerer Editor mit Hinweis, ohne Beispiel.</p><p>Neu in <strong>0.1.47</strong>: <a href="./blockly-audit">Aktionsfunktionen mit Parametern und bedingte Rückgabewerte</a>. Der Gesamtkatalog enthält jetzt 166 unterstützte Blocktypen.</p><p>Neu in <strong>0.1.46</strong>: <strong>Sprache → System / DE / EN / FR</strong> gilt jetzt für die gesamte Oberfläche, Dialoge, Status, Bestätigungen und Validierungshinweise. Eigene Namen, Entitätsdaten, Paketbeschriftungen und YAML/Jinja werden nicht automatisch übersetzt.</p><p><img src="'+o+`" alt="Deutsche Oberfläche; Testdaten und eigene Namen bleiben im Original"></p><p>Neu in <strong>0.1.45</strong>: vier doppelte Toolbox-Einträge entfernt. Zahl nur unter Mathematik, Text unter Text, Farbe unter Farbe, erweiterbares UND/ODER/NICHT unter Logik. Werte enthält Prozent; bestehende Projekte bleiben kompatibel.</p><p>Neu in <strong>0.1.44</strong>: durchsuchbare Aktions- und Zielauswahl, fünf Zielarten, Mehrfachziele und manuelle Jinja-Eingaben. <a href="./entities">Bedienung und Grenzen</a>.</p><p>Neu in <strong>0.1.42</strong>: drei kompakte, gleich große Buttons beim YAML-Import, bei Bedarf mit zweizeiligen Beschriftungen. Rechts entfernt <strong>Eingabefeld leeren</strong> den Einfügetext und die Importfehlermeldung. Die aktuelle Automation und der Ersetzen-Haken bleiben erhalten.</p><p>Neu in <strong>0.1.41</strong>: 15 verschachtelte Jinja-Blocktypen, insgesamt 163 Typen. Entitäten, Filter, Vergleiche, Berechnungen und einfache if/else-/for-Templates bearbeiten. Originaltext bleibt unverändert bis zur Bearbeitung; nicht unterstützte Templates bleiben Originalblocks. <a href="./advanced#jinja-experimentell">Zerlegung und Grenzen</a>.</p><p>Seit <strong>0.1.40</strong> haben Blocks in allen Themes <strong>16-px-Schrift</strong>. Das Blockmenü bleibt fest bei <strong>100 Prozent</strong>: Einpassen, Mausrad und Zoomregler verändern nur den Arbeitsbereich. Startzoom 100 Prozent, Einpassen 85–120 Prozent, manueller Zoom 50–240 Prozent. Große Automationen bleiben verschiebbar; Einpassen verkleinert sie höchstens auf 85 Prozent, damit die Schrift lesbar bleibt. Geprüft in Full HD, 2560 px und HiDPI.</p><p>Neu in <strong>0.1.39</strong>: 148 Blocktypen, erweiterte HA-Auslöser und Bedingungen, Ziele/Variablen/Optionen, Warten auf Auslöser, Parallelzweige und Aktionsgruppen sowie <strong>Jinja (experimentell)</strong> mit Erkennung und unverändertem Originaltext. <a href="./advanced">Anleitung, Beispiele, Grenzen und Quellen</a>.</p><p><strong>Sprache → Systemsprache / DE / EN / FR</strong> nutzt die bevorzugten Browsersprachen; nicht unterstützte Sprachen fallen auf Englisch zurück. App-Beschriftungen, Dropdowns, Hilfetexte, Kategorien und Dialoge werden übersetzt. Der Wechsel sichert das gültige Projekt und lädt den Editor neu; bei unvollständigen Blocks oder gesperrtem Speicher bleibt die aktuelle Ansicht erhalten. Technische IDs, Variablennamen, eigene Texte, Templates und YAML bleiben unverändert. Blockpakete behalten die Sprache ihrer Autoren. <a href="/fr/projects/blocks-for-ha/">Französische Dokumentation</a>; Blockbilder im Katalog sind jeweils DE/EN/FR.</p><p>Neu in <strong>0.1.18</strong>: <a href="./custom-blocks">Eigener Block-/Template-Editor</a> als 95%-Dialog, Kategorie Benutzerdefiniert, mehrere Blocks pro Paket, kopierbarer JSON-Code und ZIP-Import/Export. <a href="./catalog/">Blockpaket-Katalog</a>.</p><p>Neu in <strong>0.1.17</strong>: Entitäten aus HA laden und in vorhandenen Blockfeldern nach Name/ID suchen. Passende Licht-/Script-/Helferfilter, manuelle IDs ohne Verbindung und serverseitige Zugangsdaten. <a href="./entities">Anleitung mit Bild und Grenzen</a>.</p><p>Neu in <strong>0.1.16</strong>: Theme-Auswahl UGSo Standard/Dark/Modern/Tritanopia und Zoom-to-fit-Knopf. Auswahl wird lokal gespeichert; eigene Blocks folgen den Paletten. <a href="./themes">Bedienung, Bilder und Originalquellen</a>. Weiterhin 111 Blocktypen.</p><p><strong>Version 0.1.47 · experimentelle HA-App.</strong> Mit visuellen Blocks entstehen native Home-Assistant-Automationen. Der Editor erzeugt YAML; Home Assistant übernimmt die Ausführung. HA-Aktionen und Ziele lassen sich aus lesenden Katalogen auswählen.</p><p>Seit <strong>0.1.25</strong> rechts <strong>YAML → Code importieren</strong> wählen, YAML einfügen und <strong>Importieren</strong> statt Speichern klicken. Ohne Haken werden Auslöser, Bedingungen und Aktionen ergänzt; Name, Einstellungen und bestehende Blockformen bleiben erhalten. Bedingungen werden gemeinsam als UND geprüft; zusätzliche Auslöser können weitere Starts verursachen. Zum vollständigen Ersetzen <strong>Aktuelle Automation vollständig ersetzen</strong> aktivieren und die Abfrage bestätigen. Unterstützt wird eine Automation als Objekt oder Liste mit einem Eintrag, maximal 1 MB. Ungültiger Code oder Abbruch lässt die aktuellen Blocks erhalten. Einfügetext bleibt beim Moduswechsel für diese Seite erhalten; nach Erfolg erscheint wieder die Ausgabe. Zum Ergänzen muss die aktuelle Automation gültig sein; vollständiger Ersatz funktioniert auch bei unvollständigen Blocks. Dateiimport über <strong>Öffnen</strong> bleibt verfügbar.</p><p>Die Blocks verwenden die klassischen Blockly-Puzzleformen (Geras) mit 16-px-Schrift. Das Menü bleibt unabhängig vom Editorzoom bei 100 Prozent. Einpassen im Arbeitsbereich nutzt 85–120 Prozent; große Automationen bleiben verschiebbar. <a href="./themes">Themes, Zoom und Lesbarkeit</a>.</p><h2 id="liste-der-blocks-und-originalplugins" tabindex="-1">Liste der Blocks und Originalplugins <a class="header-anchor" href="#liste-der-blocks-und-originalplugins" aria-label="Permalink to &quot;Liste der Blocks und Originalplugins&quot;">​</a></h2><p>Neu in <strong>0.1.13</strong>: 18 Blocks für <strong>Timeouts, Objekt, Logik, Schleifen und Listen</strong>. Native HA-Pausen mit Einheiten/Laufzeitwerten, Warten bis mit Timeout, Lauf stoppen, Wiederholungen, Dictionary-Zugriffe und -Zuweisungen, Fallauswahl, Bereichsvergleich, Ersatzwert und Listen. <a href="./flow">ioBroker / Original-Blockly / UGSo: Zuordnung und Grenzen</a>.</p><p>Neu in <strong>0.1.12</strong>: <strong>Konvertierung</strong> mit neun Blocks für Zahl, Boolean, String, Typ, Datum/Zeit, Datumsformat/-bestandteile, Zeitdifferenz und JSON. Dynamische Formatauswahl und JSON-Formatierung per Checkbox. JSONata bleibt als Erweiterung vorgemerkt. <a href="./conversion">Anleitung und ioBroker-Gegenüberstellung</a>.</p><p>Neu in <strong>0.1.11</strong>: sieben Blocks für <strong>Datum und Zeit</strong>, mit Uhrzeitvergleichen, Zeiträumen über Mitternacht, Datumswerten, Kalenderbeginn, nächsten Sonnenereignissen, Zeitberechnung und Formatierung. <a href="./time">Anleitung und ioBroker-Gegenüberstellung</a>.</p><p>Neu in <strong>0.1.10</strong>: <strong>Erhöhe Variable um …</strong> im Variablen-Menü mit Schritt <code>1</code>, negativen und dezimalen Schritten. <a href="./blocks#erhohen-und-verringern-seit-0-1-10">Bild, Beispiel und Voraussetzungen</a>.</p><p>Neu in <strong>0.1.9</strong>: Kategorie <strong>Logik</strong> mit Vergleich, kompaktem UND/ODER, NICHT, wahr/falsch, null und bedingter Wertauswahl. Variablen unterstützen jetzt auch Boolean und null. <a href="./blocks#logik-blocks-seit-0-1-9">Alle sechs neuen Blocks mit Bildern und Beispiel</a>.</p><p>Die <a href="./blocks">Liste aller 163 Blocks</a> zeigt jeden Block mit Bild und Funktionsbeschreibung. Die Tabelle der Originalplugins verlinkt direkt auf die jeweiligen Quellen.</p><p>Neu in <strong>0.1.8</strong>: <strong>Variablen → Variable erstellen …</strong>, Setzen-/Lesen-Blocks und die Kategorie <strong>Templates</strong> mit eigenen Wert- und Bedingungsblocks. Variablen erzeugen native HA-<code>variables</code>-Aktionen; Lesen erzeugt <code>{{ name }}</code>. Jinja wird erst in HA ausgewertet. <a href="./blocks#variablen-und-templates-verwenden">Anleitung, Beispiel und Importgrenzen</a>.</p><p>Neu in 0.1.7: <strong>Suche am Menüende</strong>, mehrzeilige Texte, Prozent-Slider, Farbe und Lichtaktion, Datum heute und abhängige Helfer-Dropdowns. Seit 0.1.58 erfolgen Erweiterungen ausschließlich über das Zahnrad, einschließlich Sonst. Entfernte Eingänge lösen ihre Blocks ab, löschen sie nicht. Das Zahnrad bleibt zum Umordnen.</p><p>Der Datumsvergleich einschließlich Jahr wird in HA mit <code>now().strftime(&#39;%Y-%m-%d&#39;)</code> ausgewertet; er verwendet die HA-Zeitzone und ist eine Bedingung, kein Auslöser. Diese Form erhält beim Import den Datumsblock; andere Template-Bedingungen erhalten den allgemeinen Template-Block. Die Lichtaktion erzeugt RGB-Farbe und Helligkeit in Prozent. Timer nutzen ihre konfigurierte Dauer; zusätzliche Parameter bleiben in der generischen HA-Aktion. Die tatsächlichen Gerätefähigkeiten müssen in HA geprüft werden.</p><p>Das eigene UGSo-Icon verbindet Haus und Puzzle-Baustein und wird in Oberfläche, Browser und HA-App verwendet. Zehn Originalplugins werden lokal ausgeliefert. Farbmischung und Zufallsfarben sind seit 0.1.15 umgesetzt; automatisch wachsende Anschlüsse und Live-Aktionsauswahl bleiben offen. Textverknüpfung und Listenbearbeitung sind umgesetzt.</p><h2 id="im-ha-app-store-installieren" tabindex="-1">Im HA-App-Store installieren <a class="header-anchor" href="#im-ha-app-store-installieren" aria-label="Permalink to &quot;Im HA-App-Store installieren&quot;">​</a></h2><p>Das gemeinsame Repository <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> hinzufügen beziehungsweise über die Repository-Aktualisierung neu laden. <strong>Blocks for HA</strong> installieren, starten und <strong>Weboberfläche öffnen</strong> wählen. Die App unterstützt amd64 und aarch64 und öffnet den Editor über HA-Ingress. Zum Öffnen ist keine zusätzliche Token-Eingabe nötig. Die App lädt Entitäten lesend über den Supervisor und schreibt keine HA-Systemdateien.</p><h2 id="start-und-dateien" tabindex="-1">Start und Dateien <a class="header-anchor" href="#start-und-dateien" aria-label="Permalink to &quot;Start und Dateien&quot;">​</a></h2><p>Der Code liegt neben Grafik Visual Studio im <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/blocks_for_ha" target="_blank" rel="noreferrer">gemeinsamen Repository</a>. Im Ordner <code>blocks_for_ha</code> mit Node.js 22.12 oder neuer:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Editor: <code>http://127.0.0.1:4180/</code>. YAML kann angezeigt, kopiert, als Datei gespeichert und wieder als Blocks geöffnet werden. Unterstützt wird eine Automation als Objekt oder Liste mit einem Eintrag. Nicht unterstützte Strukturen werden zurückgewiesen. JSON-Projekte erhalten zusätzlich Blockpositionen; der Browser sichert den letzten Stand lokal.</p><h2 id="iobroker-unsere-blocks-vorhandene-funktionen" tabindex="-1">ioBroker / unsere Blocks: vorhandene Funktionen <a class="header-anchor" href="#iobroker-unsere-blocks-vorhandene-funktionen" aria-label="Permalink to &quot;ioBroker / unsere Blocks: vorhandene Funktionen&quot;">​</a></h2><p>111 Blocktypen einschließlich des Automationsrahmens; Variablen, Templates, Datum/Zeit und Konvertierung sind im Katalog beschrieben:</p><table tabindex="0"><thead><tr><th>ioBroker-Konzept</th><th>UGSo Blocks für HA</th><th>HA-Ausgabe</th></tr></thead><tbody><tr><td>Script-Rahmen</td><td>Automation</td><td><code>triggers</code>, <code>conditions</code>, <code>actions</code></td></tr><tr><td>Zustandstrigger</td><td>Zustand erreicht</td><td><code>trigger: state</code></td></tr><tr><td>Zahlenprüfung als Trigger</td><td>Grenzübertritt über/unter</td><td><code>trigger: numeric_state</code></td></tr><tr><td>Zeitplan</td><td>Uhrzeit</td><td><code>trigger: time</code></td></tr><tr><td>Astro</td><td>Sonnenaufgang/-untergang</td><td><code>trigger: sun</code></td></tr><tr><td>Systemstart, anderer Lebenszyklus</td><td>HA startet</td><td><code>trigger: homeassistant</code></td></tr><tr><td>Zustandsvergleich</td><td>Zustand ist</td><td><code>condition: state</code></td></tr><tr><td>Zahlenvergleich</td><td>Zahl über/unter</td><td><code>condition: numeric_state</code></td></tr><tr><td>UND/ODER/NICHT</td><td>Alle/mindestens eine/keine Bedingungen</td><td><code>and</code>, <code>or</code>, <code>not</code></td></tr><tr><td>Steuere/umschalten</td><td>Ein/Aus/Umschalten</td><td>Passende Aktion der Entitätsdomain</td></tr><tr><td>Adapteraktion</td><td>Generische HA-Aktion</td><td><code>action</code>, optional Entitätsziel und JSON-Daten</td></tr><tr><td>Pause</td><td>Warte Sekunden</td><td><code>delay</code></td></tr><tr><td>Falls/sonst falls/sonst</td><td>Erweiterbarer Falls-Block</td><td><code>if</code> oder <code>choose</code></td></tr><tr><td>Zahl</td><td>Zahlen-Wertblock, auch als Shadow-Standardwert</td><td>Konstante für Grenze oder Wartezeit</td></tr><tr><td>Text</td><td>Text-Wertblock mit Shadow</td><td>Logmeldung</td></tr><tr><td>Prozent</td><td>Slider-Wert 0–100</td><td>Number-Konstante</td></tr><tr><td>Farbe</td><td>Farb-Wertblock</td><td>Colour-Wert</td></tr><tr><td>Lichtfarbe</td><td>Licht mit Farbe/Helligkeit</td><td><code>rgb_color</code>, <code>brightness_pct</code></td></tr><tr><td>Datum</td><td>Datum heute ist/ab/bis</td><td>HA-Template-Bedingung</td></tr><tr><td>Helfer steuern</td><td>Abhängige Aktionsauswahl</td><td>Schalter/Zähler/Timer</td></tr><tr><td>Debug-Ausgabe</td><td>Log mit Schweregrad</td><td><code>system_log.write</code></td></tr><tr><td>Script steuern</td><td>Starten/stoppen/aufrufen und warten</td><td><code>script.turn_on</code>, <code>script.turn_off</code> oder direkter Aufruf</td></tr><tr><td>Aktualisiere State, andere Bedeutung</td><td>Entität aktualisieren</td><td><code>homeassistant.update_entity</code></td></tr></tbody></table><p>Name, Beschreibung, ID und Ausführungsmodi <code>single</code>, <code>restart</code>, <code>queued</code>, <code>parallel</code> sind vorhanden. Für queued/parallel lässt sich die maximale Anzahl festlegen. Drei Beispiele zeigen Licht, Batterie und Abendlicht.</p><h2 id="system-blocks-ab-version-0-1-6" tabindex="-1">System-Blocks ab Version 0.1.6 <a class="header-anchor" href="#system-blocks-ab-version-0-1-6" aria-label="Permalink to &quot;System-Blocks ab Version 0.1.6&quot;">​</a></h2><p>Die Kategorie <strong>System</strong> enthält drei neue Aktionsblocks. Unter <strong>Werte</strong> steht zusätzlich ein grüner <strong>Text</strong>-Block bereit. Er besitzt einen String-Output und passt in den Meldungseingang des Log-Blocks; Zahlen und Bedingungen passen dort nicht hinein.</p><table tabindex="0"><thead><tr><th>ioBroker</th><th>Unser Block</th><th>Bedienung und HA-Verhalten</th></tr></thead><tbody><tr><td>Debug-Ausgabe</td><td>Log</td><td>Meldung als Text-Shadow oder eigener Textblock; Dropdown Info, Warnung, Fehler, Debug oder Kritisch. Erzeugt <code>system_log.write</code>.</td></tr><tr><td>Script steuern</td><td>HA-Script</td><td>Script-ID eingeben; starten ohne Warten, stoppen oder aufrufen und warten wählen.</td></tr><tr><td>Aktualisiere State</td><td>Entität aktualisieren</td><td>Fordert mit <code>homeassistant.update_entity</code> eine Aktualisierung an. Setzt keinen Zustand und besitzt keine ioBroker-<code>ack</code>-Semantik.</td></tr><tr><td>Text</td><td>Text-Wertblock</td><td>Editierbarer Text für Logmeldungen, im Projekt und YAML erhalten.</td></tr></tbody></table><p><strong>Starten ohne Warten</strong> erzeugt <code>script.turn_on</code>; die Automation läuft anschließend weiter. <strong>Stoppen</strong> erzeugt <code>script.turn_off</code>. <strong>Aufrufen und warten</strong> erzeugt einen direkten <code>script.name</code>-Aufruf: Die Automation wartet auf dessen Abschluss; Fehler können an den Aufrufer weitergegeben werden. Script-Parameter werden weiterhin über die generische HA-Aktion eingegeben.</p><p>Beim YAML-Import werden genau passende Systemaktionen als eigene Blocks erkannt. Zusätzliche Daten, etwa ein eigener Logger oder Script-Variablen, bleiben in der generischen HA-Aktion erhalten. Die Aktualisierung wird von der jeweiligen Integration unterstützt oder begrenzt. Logmeldungen entstehen erst bei Ausführung in HA; Info und Debug können durch die HA-Logkonfiguration ausgefiltert werden.</p><p>Referenzen: <a href="https://www.home-assistant.io/integrations/system_log/" target="_blank" rel="noreferrer">HA-Systemprotokoll</a>, <a href="https://www.home-assistant.io/integrations/script/" target="_blank" rel="noreferrer">HA-Scripts</a>, <a href="https://www.home-assistant.io/integrations/homeassistant/" target="_blank" rel="noreferrer">HA-Core-Aktionen</a>.</p><h2 id="zahnrad-falls-erweitern" tabindex="-1">Zahnrad: Falls erweitern <a class="header-anchor" href="#zahnrad-falls-erweitern" aria-label="Permalink to &quot;Zahnrad: Falls erweitern&quot;">​</a></h2><p>Wie beim vertrauten ioBroker-Editor öffnet das Zahnrad eine kleine Arbeitsfläche. Dort lassen sich <strong>sonst falls</strong>-Elemente an den Falls-Rahmen anhängen und ein optionaler <strong>sonst</strong>-Zweig ergänzen. Die jeweiligen Bedingungen und Aktionen werden anschließend im Hauptblock eingesteckt.</p><ul><li>Ein Falls-Zweig erzeugt <code>if</code>/<code>then</code>, optional <code>else</code>.</li><li>Mehrere Zweige erzeugen <code>choose</code>, der Sonst-Zweig wird <code>default</code>.</li><li>HA führt den ersten passenden Zweig aus. Weitere passende Zweige werden nicht ausgeführt.</li><li>Entfernte Zweige lösen ihre verbundenen Blocks ab. Diese müssen wieder verbunden oder entfernt werden, bevor exportiert werden kann.</li><li>YAML-Import und JSON-Projekte erhalten die Verzweigungen. Alte Projekte behalten ihre bisherigen Sonst-Aktionen.</li></ul><p>UND/ODER/NICHT besitzt ein eigenes Zahnrad für 1–100 seitliche Bedingungseingänge. Auslöser und Aktionen lassen sich als Ketten erweitern. Sonnen-, Vergleichs- und Schaltvarianten werden direkt im Dropdown gewählt. Die generische HA-Aktion verwendet zunächst JSON-Daten; ein visueller Datenfeld-Mutator ist noch geplant.</p><h2 id="andocken-und-bedienung" tabindex="-1">Andocken und Bedienung <a class="header-anchor" href="#andocken-und-bedienung" aria-label="Permalink to &quot;Andocken und Bedienung&quot;">​</a></h2><p>Das Kategorienmenü ist dunkel, die aufgeklappte Blockauswahl hell. Werte sind grün, Auslöser orange, Bedingungen violett und Aktionen blau. Die Kategorienmarkierungen zeigen die jeweilige Blockgruppe; die ausgewählte Kategorie ist zusätzlich hervorgehoben.</p><ul><li><strong>Output links / Werteingang rechts:</strong> Bedingungen liefern Boolean-Werte. Sie passen in „Nur wenn“, „Falls“, „sonst falls“ und UND/ODER/NICHT. Zahlen liefern Number-Werte und passen in Grenzen oder Wartezeiten. Die Typprüfung verhindert unpassende Verbindungen.</li><li><strong>Previous oben / Next unten:</strong> Auslöser und Aktionen bilden jeweils eigene Ketten; sie können nicht miteinander vertauscht werden.</li><li><strong>Statement-Innenraum:</strong> „mache“ und „sonst“ nehmen Aktionsfolgen auf. Bedingungen gehören an die seitlichen Werteingänge.</li><li><strong>Shadow-Zahlen:</strong> Grenzen und Wartezeiten haben editierbare Standardwerte. Ein herausgezogener Zahlenblock kann sie ersetzen. Wird dieser entfernt, erscheint der Standardwert wieder. Logmeldungen nutzen String-Textblocks mit editierbarem Shadow. Sensor- und Entitäts-Wertblocks sind noch nicht umgesetzt.</li><li><strong>Kontextmenü:</strong> Rechtsklick beziehungsweise langes Drücken bietet die Blockly-Funktionen, etwa Duplizieren, Kommentar, Einklappen, Deaktivieren, Löschen und Hilfe. Hilfe führt hierher. Kommentare bleiben im JSON-Projekt; sie werden noch nicht als YAML-Kommentare exportiert.</li><li><strong>Deaktivieren:</strong> Deaktivierte Aktionen und Auslöser werden beim Export übersprungen. Deaktivierte Bedingungen werden ausgelassen. Pflichtinhalte bleiben erforderlich; fehlende Auslöser, leere Falls-Bedingungen oder leere Aktionszweige verhindern den Export.</li><li><strong>Papierkorb:</strong> Blocks löschen, den Papierkorb öffnen und gelöschte Blocks zurück auf die Arbeitsfläche ziehen. Der Verlauf ist auf die aktuelle Sitzung begrenzt. Rückgängig/Wiederholen steht zusätzlich bereit.</li><li><strong>Einfügemarkierung:</strong> Blockly zeigt beim Ziehen die mögliche Andockposition an.</li></ul><p>Projektdateien aus Version 0.1.4 und früher werden automatisch auf die neue Anschlussstruktur umgestellt. Alte Bedingungsketten werden als UND-Gruppen mit derselben YAML-Bedeutung erhalten. Die bestehenden YAML-Dateien bleiben importierbar.</p><h2 id="blockly-bibliothek-und-verbindlicher-entwicklungsstand" tabindex="-1">Blockly-Bibliothek und verbindlicher Entwicklungsstand <a class="header-anchor" href="#blockly-bibliothek-und-verbindlicher-entwicklungsstand" aria-label="Permalink to &quot;Blockly-Bibliothek und verbindlicher Entwicklungsstand&quot;">​</a></h2><p>Wir verwenden bereits <strong>Blockly 13.3.0</strong>, die originale Bibliothek, statt eine eigene Block-Engine zu entwickeln. Blockly übernimmt Arbeitsfläche, Kategorie-Toolbox und Flyouts, Verbindungen mit Typprüfung, Shadow-Blocks, Mutatoren, Kontextmenü, Zoom, Papierkorb und Einfügemarkierungen. Unsere HA-Blocks, Strukturvalidierung, Projektmigration und der YAML-Generator sind eigener UGSo-Code. Es wird kein ioBroker-JavaScript ausgeführt.</p><p>Die <a href="https://docs.blockly.com/guides/get-started/workspace-anatomy/" target="_blank" rel="noreferrer">Originaldokumentation zur Arbeitsfläche und zu Blockteilen</a> und die <a href="https://raspberrypifoundation.github.io/blockly-samples/" target="_blank" rel="noreferrer">Blockly-Beispiele</a> dienen als Referenz für vertraute Bedienmuster. Bibliotheksupdates werden bewusst mit Verbindungs-, Import-/Export- und Browserprüfungen übernommen.</p><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Stand in 0.1.16 / nächster Schritt</th></tr></thead><tbody><tr><td>Anschlussgeometrie und Typprüfung</td><td>Boolean-Bedingungen und Number-Werte seitlich; Auslöser/Aktionen als getrennte Statement-Ketten umgesetzt</td></tr><tr><td>Erweiterbare Blocks</td><td>Falls, UND/ODER/NICHT, Fallauswahl, Objekte und Listen umgesetzt; Aktionsdaten später als visuelle Felder</td></tr><tr><td>Standardwerte</td><td>Shadow-Zahlen und Textblocks umgesetzt; Entitäts-Wertblocks offen</td></tr><tr><td>Sensorwerte und Attribute</td><td>Eigene Wert-Blocks offen; über Templates bereits nutzbar. Typumwandlung als Konvertierungs-Blocks vorhanden</td></tr><tr><td>Editorbedienung</td><td>Kontextmenü, Hilfe, Deaktivieren, Papierkorb-Wiederherstellung, Zoom und Einfügemarkierung vorhanden</td></tr><tr><td>Kommentare</td><td>Im Projekt erhalten; YAML-Kommentare und eigener Kommentarblock offen</td></tr><tr><td>Menü und Blockfarben</td><td>Dunkles Kategorienmenü, helle Blockauswahl, getrennte Gruppenfarben umgesetzt</td></tr><tr><td>ioBroker-Kategorien</td><td>System, Datum/Zeit, Konvertierung, Timeouts, Objekt und Logik geprüft; Unterschiede zur HA-Ausführung dokumentiert</td></tr><tr><td>JSONata</td><td>Vorgemerkt; native Objekt-/Listen-Zugriffe und optionalen HA-Runtimeadapter prüfen</td></tr><tr><td>Veröffentlichung und Updates</td><td>Jede neue HA-App von Anfang an im gemeinsamen Repository mit installierbarem Paket; Paket- und Oberflächenversion gemeinsam anheben</td></tr><tr><td>HA-Verbindung, Katalog und Plugins</td><td>Lesende Entitätsanbindung und deklarative Blockpakete vorhanden; Live-Aktionsauswahl und Paketupdates offen</td></tr></tbody></table><p>Diese Seite hält umgesetzte Funktionen und offene Aufgaben zusammen fest und wird mit jeder Erweiterung gepflegt.</p><h2 id="eigene-blocks-umgesetzt-und-roadmap" tabindex="-1">Eigene Blocks: umgesetzt und Roadmap <a class="header-anchor" href="#eigene-blocks-umgesetzt-und-roadmap" aria-label="Permalink to &quot;Eigene Blocks: umgesetzt und Roadmap&quot;">​</a></h2><p>Seit 0.1.18 sind der eigene HA-Editor, Blockly-Vorschau, Wert/Bedingung/Aktion/Auslöser, typisierte Felder und Werteingänge, Paketimport/export und eingebettete Projektdefinitionen umgesetzt. <a href="./custom-blocks">Bedienung und Grenzen</a>.</p><p>Die Einbettung der originalen Blockly Developer Tools, Dropdowns, Bilder, Variablenfelder, Statement-Container, Mutatoren, dynamische Eingänge, Paketupdates und Deinstallation bleiben vorgemerkt.</p><h2 id="system-stand-und-nachste-schritte" tabindex="-1">System: Stand und nächste Schritte <a class="header-anchor" href="#system-stand-und-nachste-schritte" aria-label="Permalink to &quot;System: Stand und nächste Schritte&quot;">​</a></h2><p>Steuern, Umschalten, Wartezeit, generische Aktionen, Log-Ausgabe, Script-Steuerung, Entität aktualisieren und Helfer steuern sind vorhanden. Entitätsauswahl ist seit 0.1.17 umgesetzt. Eigene Blocks für Kommentar, Zustand/Attribute als Werte, Existenz/Verfügbarkeit und Zahlen-/Texthelfer folgen schrittweise. ioBroker-<code>ack</code>, Adapterinstanzen und Datenpunkt-Erzeugung haben kein direktes HA-Gegenstück.</p><p>Die vollständige <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/blocks_for_ha/docs/iobroker-comparison.de.md" target="_blank" rel="noreferrer">Gegenüberstellung mit Umsetzungsstatus</a> wird bei jeder Erweiterung aktualisiert. Deklarative Blockpakete und Beispielkatalog sind seit 0.1.18 vorhanden.</p><h2 id="prufung-und-original" tabindex="-1">Prüfung und Original <a class="header-anchor" href="#prufung-und-original" aria-label="Permalink to &quot;Prüfung und Original&quot;">​</a></h2><p>Der Editor prüft die unterstützte Struktur. Entitäts-IDs werden gesucht oder manuell eingegeben; installierte Aktionen und echte HA-Ausführung sind damit nicht verifiziert. Vor Verwendung Beispiel-Entitäten ersetzen und Aktionen in HA prüfen. Der Editor schreibt keine HA-Systemdateien.</p><p>Built with <a href="https://www.blockly.com/" target="_blank" rel="noreferrer">Blockly</a>. Eigene HA-Blocks, kein ioBroker-Fork. Eigener Code und Blockly: Apache-2.0; YAML-Bibliothek: ISC. Lizenztexte werden mitgeliefert.</p><h2 id="built-with-blockly" tabindex="-1">Built with Blockly <a class="header-anchor" href="#built-with-blockly" aria-label="Permalink to &quot;Built with Blockly&quot;">​</a></h2><p>Blockly ist eine Open-Source-Entwicklerbibliothek der Raspberry Pi Foundation, ursprünglich bei Google entwickelt. Seit <strong>0.1.19</strong> verwendet die App das unveränderte offizielle Badge mit 32 Pixel Höhe, Freiraum und Link zu Blockly. Beide SVG-Varianten werden lokal ausgeliefert. <a href="https://docs.blockly.com/guides/app-integration/attribution/" target="_blank" rel="noreferrer">Originalhinweise zur Attribution</a>.</p><p><a class="blockly-attribution" href="https://www.blockly.com/" target="_blank" rel="noopener noreferrer"><img class="badge-light" src="`+t+'" alt="Built with Blockly" width="87" height="32"><img class="badge-dark" src="'+n+'" alt="Built with Blockly" width="87" height="32"></a></p><h2 id="home-assistant-seitenleiste" tabindex="-1">Home-Assistant-Seitenleiste <a class="header-anchor" href="#home-assistant-seitenleiste" aria-label="Permalink to &quot;Home-Assistant-Seitenleiste&quot;">​</a></h2><p>Seit <strong>0.1.20</strong> verwendet der Eintrag das einfarbige Baustein-Icon <code>mdi:toy-brick-outline</code>. App aktualisieren, neu starten und <strong>In der Seitenleiste anzeigen</strong> aktivieren. Bei alter Anzeige die HA-Seite neu laden. Die native App-Konfiguration verwendet MDI-Icons; das farbige UGSo-Icon bleibt im App-Store und Editor. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">HA-Konfiguration</a> · <a href="https://pictogrammers.com/library/mdi/icon/toy-brick-outline/" target="_blank" rel="noreferrer">Originalicon</a>.</p><h2 id="arbeitsbereichssuche-und-tastaturbedienung" tabindex="-1">Arbeitsbereichssuche und Tastaturbedienung <a class="header-anchor" href="#arbeitsbereichssuche-und-tastaturbedienung" aria-label="Permalink to &quot;Arbeitsbereichssuche und Tastaturbedienung&quot;">​</a></h2><p>Seit <strong>0.1.21</strong> findet <strong>Suchen</strong> in der Werkzeugleiste bereits platzierte Blocks, einschließlich eigener HA- und Benutzerdefiniert-Blocks. Die Suche am Menüende findet weiterhin verfügbare Bausteine zum Hinzufügen. Suchen verändert die Ansicht, nicht YAML oder das gespeicherte Projekt.</p><p>Bei Fokus im Arbeitsbereich öffnet <strong>Strg/Cmd+F</strong> die Suche. <strong>Enter</strong> wählt den nächsten Treffer, <strong>Umschalt+Enter</strong> den vorherigen. <strong>Escape</strong> schließt die Suche und fokussiert den aktuellen Block. Die Suchknöpfe sind deutsch und zugänglich beschriftet.</p><p>Der Knopf <strong>?</strong> öffnet die Tastaturhilfe. Blockly 13.3 bringt Navigation mit: Tab führt in den Arbeitsbereich, Pfeiltasten bewegen den Fokus durch Blocks und Felder, Enter bearbeitet Felder, T fokussiert die Toolbox und M nimmt einen Block auf. Zusätzlich aktiviert: Pos1/Ende innerhalb eines Blocks, Bild auf/ab innerhalb eines Stapels, Strg/Cmd+Pos1/Ende zum ersten/letzten Block und Strg/Cmd+Pfeiltasten zum Scrollen. Eingabefelder und Dialoge behalten ihre normale Textbearbeitung. Die Screenreader-Bedienung ist noch nicht unabhängig geprüft.</p><p>Originalquellen: <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/workspace-search" target="_blank" rel="noreferrer">workspace-search-Plugin</a>, <a href="https://docs.blockly.com/guides/configure/keyboard-nav/" target="_blank" rel="noreferrer">Blockly-Tastaturnavigation</a>.</p><p>Seit <strong>0.1.23</strong> benötigen Einleitung und Automationseinstellungen weniger Höhe: kleinere Überschrift und Abstände sowie 32 Pixel hohe Projektfelder und Knöpfe geben der Arbeitsfläche mehr Platz. HA-Verbindungsstatus und Entitätsanzahl stehen jetzt ebenfalls in der Einstellungsleiste und sind auch auf schmalen Bildschirmen sichtbar.</p><p>Seit <strong>0.1.24</strong> klappt der Pfeil rechts oben die HA-Ausgabe nach rechts ein. Blockly erweitert sich in den frei werdenden Platz. Die schmale Leiste <strong>HA-Ausgabe</strong> öffnet das Panel wieder; der Zustand wird lokal gespeichert. Auf Mobilgeräten bleibt eine kompakte Zeile unter dem Editor. Das Einklappen verändert weder YAML noch Projekte.</p><p>Seit <strong>0.1.28</strong>: Zustandslisten über <strong>Zustände als JSON-Liste</strong>, z. B. <code>[&quot;1_single&quot;,&quot;1_double&quot;]</code>; optionale Trigger-IDs in allen Standardauslösern; <strong>Ausgelöst durch ID</strong> als native Trigger-Bedingung (einzelne ID oder JSON-Liste). Allgemeine HA-Aktionen unterstützen <strong>Ziele als JSON-Liste</strong>, optionale Metadaten und erhalten ausdrücklich leere Datenobjekte. Vierfach-Taster mit vier <code>choose</code>-Zweigen sind vollständig importierbar.</p><p><strong>Einzelne Automation · HA-Editor</strong> gibt keine oberste <code>id</code> aus. Trigger-IDs bleiben erhalten. Projekt und <strong>automations.yaml-Liste</strong> behalten eine vorhandene Automations-ID.</p><p><a href="https://www.home-assistant.io/docs/automation/trigger/#trigger-id" target="_blank" rel="noreferrer">Home Assistant: Trigger IDs</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#trigger-condition" target="_blank" rel="noreferrer">Trigger condition</a></p><p>Seit <strong>0.1.29</strong> nutzt die Blockly-Arbeitsfläche die vollständige Höhe des Editorbereichs bis zur Legende. Eine höhere YAML-Spalte vergrößert auch die Arbeitsfläche; die Ausgabe bleibt einklappbar.</p><p>Seit <strong>0.1.30</strong>: Ein Zeit-Auslöser akzeptiert über <strong>Uhrzeiten als JSON-Liste</strong> mehrere feste Uhrzeiten, z. B. <code>[&quot;10:00:00&quot;,&quot;13:00:00&quot;,&quot;19:00:00&quot;]</code>. <strong>Jede Änderung</strong> im Zustandsauslöser lässt <code>to</code> weg; <strong>Entitäten als JSON-Liste</strong> überwacht mehrere Entitäten. Ohne <code>to</code> reagiert HA auch auf Attributänderungen. Der Ereignis-Auslöser unterstützt z. B. <code>timer.finished</code> und einen optionalen JSON-Datenfilter. Die native Zeitbedingung erhält <code>before</code>/<code>after</code> unverändert; feste Uhrzeiten, nach inklusive und vor exklusiv, auch über Mitternacht. Gleiche Grenzen entsprechen ganztägig. Zeithelfer, Zeit-Templates und Wochentagsfilter bleiben hier noch außerhalb des unterstützten Imports. Die vollständige Poolpumpen-Automation bleibt einschließlich mehrzeiligem Timer-Template und verschachteltem <code>choose</code> erhalten.</p><p><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">Home Assistant: triggers</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#time-condition" target="_blank" rel="noreferrer">Time condition</a></p><p>Seit <strong>0.1.31</strong> unterstützt der neue Block den nativen Auslöser temperature.changed. Ziel (JSON): entity_id als Text oder Liste. Schwelle (JSON): type any, above, below, between oder outside. any benötigt nur type; above/below benötigen value, between/outside value_min und value_max. Zahlen: number plus unit_of_measurement (°C/°F). Referenzen: entity (sensor, number oder input_number). Optional ist eine Trigger-ID. Andere Zielarten (Bereich/Gerät/Label) sind noch nicht importierbar. MQTT-Topics, qos/retain/evaluate_payload und mehrzeilige JSON-/Jinja-Payloads bleiben erhalten.</p><p><a href="https://www.home-assistant.io/triggers/temperature.changed/" target="_blank" rel="noreferrer">Home Assistant: temperature.changed</a></p><p><strong>0.1.32:</strong> Kalender und Antwortvariablen. <a href="./blocks">→</a></p><p><strong>0.1.33:</strong> Numerische Auslöser mit Haltezeit. <a href="./blocks">→</a></p><p><strong>0.1.34:</strong> Mehrere Variablen in einer Aktion. <a href="./blocks">→</a></p><p><strong>0.1.35:</strong> Wartezeit als Zeittext oder Template. <a href="./blocks">→</a></p><p><strong>0.1.36:</strong> Dynamische HA-Aktionsnamen. <a href="./blocks">→</a></p><p><strong>0.1.37:</strong> <a href="./blocks">Zeitmuster-Auslöser</a>.</p><p><strong>0.1.38:</strong> <a href="./blocks">Dynamische Zielentitäten</a>.</p>',105)])])}const f=r(d,[["render",l]]);export{k as __pageData,f as default};
